(() => { const g=__dmh,P=g.player,V=P.pos.constructor; g.godMode=true; for(let i=0;i<g.zones.length;i++)g.unlockZone(i,true); g.phase='Intermission'; g.phaseTimer=1e9;
const sp=g.spawnPoints.filter(s=>{const [a,b]=g.cellOf(s.pos.x,s.pos.z); return g.navFree(a,b);}).map(s=>s.pos);
const L=g.map.enemies; const stats={debris:0, settled:0, floatSettled:0, sunkSettled:0, noGround:0, stillAir:0, origin0:0}; const ex=[]; const seen=new Set();
for(let round=0; round<10; round++){
  const s=sp[(round*7)%sp.length]; P.pos.set(s.x+300,114,s.z+300); P.vel.set(0,0,0);
  for(let i=0;i<14;i++){ const p=sp[Math.floor(Math.random()*sp.length)]; g.spawnEnemy(L[Math.floor(Math.random()*L.length)], new V(p.x+(Math.random()-0.5)*200,100,p.z+(Math.random()-0.5)*200), false,-1,1,1,0,false); }
  for(let t=0;t<14;t++){ window.__dmhHold=false; __sim(30); P.pos.set(s.x+300,114,s.z+300); P.vel.set(0,0,0);
    for(const E of g.enemies){ if(E.dead||E.emerge>0||Math.random()>0.35)continue; const d=E.pos.clone().sub(P.pos).normalize(); E.takeHit(E.maxHealth*(0.3+Math.random()*0.5),E.pos.clone(),d,Math.random()<0.3); }
    for(const Q of g.fx.parts){ if(Q.kind!=='creature'||seen.has(Q)) continue;
      if(Q.groundY<-1e8){ seen.add(Q); stats.debris++; stats.noGround++; if(ex.length<12) ex.push('noGround @'+Math.round(Q.pos.x)+','+Math.round(Q.pos.y)+','+Math.round(Q.pos.z)); continue; }
      if(Q.settled){ seen.add(Q); stats.debris++; stats.settled++; const h=g.phys.raycastDown(new V(Q.pos.x,Q.pos.y+60,Q.pos.z),3000,false); const gy=h?h.point.y:-1e9; const d=Q.pos.y-gy; if(d>25){stats.floatSettled++; if(ex.length<12) ex.push('float '+Math.round(d)+' @'+Math.round(Q.pos.x)+','+Math.round(Q.pos.y)+','+Math.round(Q.pos.z));} else if(d<-25) stats.sunkSettled++; }
      else if(Q.age>3){ seen.add(Q); stats.debris++; stats.stillAir++; if(ex.length<12) ex.push('air age '+Q.age.toFixed(1)+' @'+Math.round(Q.pos.x)+','+Math.round(Q.pos.y)+','+Math.round(Q.pos.z)+' gy '+Math.round(Q.groundY)); }
    }
  }
}
return JSON.stringify({map:g.map.name,stats,ex}); })()
